def build(key, v):
    rom = bytearray(open(v['src'], 'rb').read())
    assert len(rom) == v['src_size'], (key, len(rom))
    assert hashlib.md5(rom).hexdigest() == v['src_md5'], key
    for off, hx, note in v['regions']:
        rom[off:off+len(bytes.fromhex(hx))] = bytes.fromhex(hx)
    out = bytes(rom)
    md5 = hashlib.md5(out).hexdigest()
    assert md5 == v['dst_md5'], (key, md5)
    open(v['dst'], 'wb').write(out)
    print('%-2s %-28s %s' % (key, v['label'], v['dst']))
    print('   MD5 %s  CRC32 %08X  size %d  regions %d'
          % (md5, zlib.crc32(out) & 0xFFFFFFFF, len(out), len(v['regions'])))

if __name__ == '__main__':
    keys = sys.argv[1:] or list(VARIANTS)
    for k in keys:
        if k not in VARIANTS:
            raise SystemExit('未知版本: ' + k)
        build(k, VARIANTS[k])
